#pragma once

// =============================================================================
// THE SPARKPLUG B PAYLOAD, ON THE WIRE
// =============================================================================
//
// org.eclipse.tahu.protobuf.Payload, encoded and decoded by hand.
//
// WHY BY HAND, AND NOT NANOPB. Eclipse Tahu's own C stack vendors nanopb 0.3.5
// generated by protoc 2.6.1 - a third-party runtime, a code generator, and two
// pinned tool versions, in a library whose entire pitch is having none of
// those. It also keeps its sequence number in a FILE-SCOPE VARIABLE
// (reset_sparkplug_sequence(), get_next_payload()), which breaks R5: two
// clients in one OpenPLC runtime would share one counter and neither would be
// conformant. So Tahu's structure is a model here and its code is not a source.
//
// The cost is honest: this is a decoder facing the network, and a bug in it is
// a remote crash. That is the same exposure MqttCodecV5 has, answered the same
// way - a truncation sweep over every offset of every corpus packet, a
// mutation fuzzer with canaries either side of the buffer, and a cross-check
// against two independent implementations in docker/testing/. Nothing here is new in
// kind.
//
// WHAT THE WIRE FORMAT ACTUALLY IS. Eight features of protobuf, no more:
// varints, fixed32, fixed64, length-delimited fields, nested messages,
// `repeated`, `oneof`, and proto2 `optional`. A field is a varint tag - the
// field number shifted left three, ORed with a wire type - then its value.
// Little-endian for the fixed widths, which is a fact about protobuf and not
// about any platform, so R9 holds.
//
// UNKNOWN FIELDS ARE SKIPPED, NOT REFUSED. Payload carries `extensions 6 to
// max` and every nested message carries its own, so a future Sparkplug or a
// vendor extension WILL arrive with field numbers this build has never heard
// of. A decoder that refused them would break on the next specification.
//
// Source: sparkplug_b.proto (eclipse-tahu/tahu) and specification section 6.4.

#include "MqttSparkplugTypes.h"
#include "MqttSparkplugValue.h"

// --- Field numbers, from the schema ---
//
// Written out rather than inferred, because they are the wire contract and a
// transposed pair is a bug no test of our own code would find - both ends
// would be consistently wrong. Cross-checked against sparkplug_b.proto in
// docker's `sparkplug-codec` phase.

// message Payload
#define MQ_SP_F_PAYLOAD_TIMESTAMP 1
#define MQ_SP_F_PAYLOAD_METRICS   2
#define MQ_SP_F_PAYLOAD_SEQ       3
#define MQ_SP_F_PAYLOAD_UUID      4
#define MQ_SP_F_PAYLOAD_BODY      5

// message Payload.Metric
#define MQ_SP_F_METRIC_NAME          1
#define MQ_SP_F_METRIC_ALIAS         2
#define MQ_SP_F_METRIC_TIMESTAMP     3
#define MQ_SP_F_METRIC_DATATYPE      4
#define MQ_SP_F_METRIC_IS_HISTORICAL 5
#define MQ_SP_F_METRIC_IS_TRANSIENT  6
#define MQ_SP_F_METRIC_IS_NULL       7
#define MQ_SP_F_METRIC_METADATA      8
#define MQ_SP_F_METRIC_PROPERTIES    9
// The value `oneof`. Exactly one of these is present on a metric that has a
// value at all; is_null true means none of them is.
#define MQ_SP_F_METRIC_INT      10
#define MQ_SP_F_METRIC_LONG     11
#define MQ_SP_F_METRIC_FLOAT    12
#define MQ_SP_F_METRIC_DOUBLE   13
#define MQ_SP_F_METRIC_BOOLEAN  14
#define MQ_SP_F_METRIC_STRING   15
#define MQ_SP_F_METRIC_BYTES    16
#define MQ_SP_F_METRIC_DATASET  17
#define MQ_SP_F_METRIC_TEMPLATE 18

// message Payload.PropertySet - two parallel repeated fields, keys and values,
// rather than a map. Index i of one goes with index i of the other.
#define MQ_SP_F_PROPERTYSET_KEYS   1
#define MQ_SP_F_PROPERTYSET_VALUES 2

// message Payload.PropertyValue
#define MQ_SP_F_PROPERTYVALUE_TYPE    1
#define MQ_SP_F_PROPERTYVALUE_IS_NULL 2
#define MQ_SP_F_PROPERTYVALUE_INT     3
#define MQ_SP_F_PROPERTYVALUE_LONG    4
#define MQ_SP_F_PROPERTYVALUE_FLOAT   5
#define MQ_SP_F_PROPERTYVALUE_DOUBLE  6
#define MQ_SP_F_PROPERTYVALUE_BOOLEAN 7
#define MQ_SP_F_PROPERTYVALUE_STRING  8
#define MQ_SP_F_PROPERTYVALUE_PROPERTYSET  9
#define MQ_SP_F_PROPERTYVALUE_PROPERTYSETS 10

// message Payload.PropertySetList
#define MQ_SP_F_PROPERTYSETLIST_SETS 1

// message Payload.Template
#define MQ_SP_F_TEMPLATE_VERSION       1
#define MQ_SP_F_TEMPLATE_METRICS       2
#define MQ_SP_F_TEMPLATE_PARAMETERS    3
#define MQ_SP_F_TEMPLATE_REF           4
#define MQ_SP_F_TEMPLATE_IS_DEFINITION 5

// message Payload.Template.Parameter. Its value fields are PropertyValue's
// numbers, 3 to 8; only 1 and 2 differ (name, then type).
#define MQ_SP_F_PARAMETER_NAME 1
#define MQ_SP_F_PARAMETER_TYPE 2

// message Payload.DataSet, its Row and its DataSetValue
#define MQ_SP_F_DATASET_NUM_COLUMNS 1
#define MQ_SP_F_DATASET_COLUMNS     2
#define MQ_SP_F_DATASET_TYPES       3
#define MQ_SP_F_DATASET_ROWS        4
#define MQ_SP_F_DATASET_ROW_ELEMENTS 1
#define MQ_SP_F_DATASETVALUE_INT     1
#define MQ_SP_F_DATASETVALUE_LONG    2
#define MQ_SP_F_DATASETVALUE_FLOAT   3
#define MQ_SP_F_DATASETVALUE_DOUBLE  4
#define MQ_SP_F_DATASETVALUE_BOOLEAN 5
#define MQ_SP_F_DATASETVALUE_STRING  6

// --- Wire types ---
#define MQ_PB_VARINT 0
#define MQ_PB_FIXED64 1
#define MQ_PB_LENGTH 2
#define MQ_PB_FIXED32 5

// Which `oneof` field a datatype's value travels in, and it is NOT intuitive.
// Specification section 6.4.17 gives each datatype its "Google Protocol Buffer
// Type", and six different datatypes share one field:
//
//   Int8, Int16, Int32, UInt8, UInt16, UInt32  ->  int_value    (10, uint32)
//   Int64, UInt64, DateTime                    ->  long_value   (11, uint64)
//   Float                                      ->  float_value  (12, float)
//   Double                                     ->  double_value (13, double)
//   Boolean                                    ->  boolean_value(14, bool)
//   String, Text, UUID                         ->  string_value (15, string)
//   Bytes, File, every array                   ->  bytes_value  (16, bytes)
//   DataSet                                    ->  dataset_value (17)
//   Template                                   ->  template_value (18)
//
// So a SIGNED Int8 of -1 travels as the uint32 0xFFFFFFFF, and an Int16 of -1
// travels as 0xFFFFFFFF too - not 0xFFFF. The width is in the DATATYPE, not in
// the encoding, and the reinterpretation on the way back out is where a codec
// like this goes wrong. Every one of those cases has a test with the bytes
// written out.
//
// Returns 0 for a datatype with no value field: Unknown, PropertySet and
// PropertySetList.
uint32_t mq_sparkplugValueField(MqttSparkplugDataType type);

// --- One property ---

struct MqttSparkplugProperty {
    // Not copied, same contract as MqttSparkplugValue: the caller owns it.
    // A Template's parameter is one of these too, with its name here.
    const char* key = nullptr;

    // [tck-id-payloads-metric-propertyvalue-type-type] This MUST be an
    // unsigned 32-bit integer. The same datatype enum as a metric, because
    // PropertyValue's own `oneof` mirrors Metric's. A PropertySet or
    // PropertySetList value is its encoded message in `as.text`, as a
    // template's is (mq_sparkplugEncodePropertySet, ...DecodePropertySet).
    MqttSparkplugDataType type = MqttSparkplugDataType::Unknown;
    bool isNull = false;

    union {
        int64_t signedValue;
        uint64_t unsignedValue;
        float float32;
        double float64;
        bool boolean;
        struct {
            const uint8_t* data;
            uint32_t length;
        } text;
    } as;

    MqttSparkplugProperty() { as.unsignedValue = 0; }
};

// A nested PropertySet or PropertySetList as a property's value: `encoded` is
// what mq_sparkplugEncodePropertySet (or ...PropertySetList) wrote. Not copied.
MqttSparkplugProperty mq_spPropertySet(const char* key, const uint8_t* encoded,
                                       uint32_t length);
MqttSparkplugProperty mq_spPropertySetList(const char* key,
                                           const uint8_t* encoded,
                                           uint32_t length);

// The two properties worth a constructor, because they are the two every
// integrator asks for.
MqttSparkplugProperty mq_spEngUnit(const char* units);
MqttSparkplugProperty mq_spQuality(int32_t quality);
MqttSparkplugProperty mq_spDescription(const char* text);

// engLow and engHigh: the range a SCADA gauge or trend should show for the
// metric. Not in the specification, which reserves only Quality; they are the
// names Eclipse Tahu and Ignition use, as engUnit is, so a host that knows
// them uses them and any other ignores them. A Double, whatever the metric's
// own type: a range is a display hint, not a value.
MqttSparkplugProperty mq_spEngLow(double low);
MqttSparkplugProperty mq_spEngHigh(double high);

// --- One metric ---
//
// A flat struct with presence flags rather than a class, because the OpenPLC
// wrapper builds these in generated code inside a scan cycle and anything with
// a constructor that allocates is unusable there.
struct MqttSparkplugMetric {
    // [tck-id-payloads-name-requirement] The name MUST be included with every
    // metric unless aliases are being used.
    // [tck-id-payloads-alias-birth-requirement] NBIRTH and DBIRTH MUST include
    // BOTH a metric name and alias.
    // [tck-id-payloads-alias-data-cmd-requirement] NDATA, DDATA, NCMD and DCMD
    // MUST only include an alias and the metric name MUST be excluded.
    //
    // Both are held here and the MESSAGE TYPE decides which is written - see
    // mq_sparkplugEncode(). That is why this struct carries both rather than
    // making the caller choose: the caller does not know, and getting it wrong
    // produces a payload a conformant host rejects.
    const char* name = nullptr;

    // A DATATYPE NO METRIC CAN CARRY - Unknown, or a property's type
    // (PropertySet, PropertySetList). The metric is still here, with its name,
    // alias and datatype, so a host application knows it exists and what it
    // is; its value is not, and value.isNull is set. A message carrying one is
    // read for everything else in it rather than refused whole.
    bool valueUnsupported = false;

    // THE METRIC CARRIED NO DATATYPE - which [tck-id-payloads-metric-datatype-
    // not-req] says NDATA, DDATA, NCMD and DCMD SHOULD NOT carry: the birth
    // declared it. value.type is then provisional, named after the wire field
    // the value arrived in (UInt64 for an integer, Float, Double, Boolean,
    // Bytes for text and bytes), until mq_sparkplugApplyDatatype() gives it
    // the declared one. MqttSparkplugHost does that from the birth, and
    // MqttSparkplugNode from the metric it declared.
    bool datatypeAbsent = false;

    uint64_t alias = 0;
    bool hasAlias = false;

    MqttSparkplugValue value;

    // Per-metric timestamp. OFF by default, and that is a deliberate departure
    // from Tahu's libraries, which stamp every metric.
    //
    // The specification lets one payload timestamp cover every metric, and a
    // per-metric one costs about eight bytes each. On the plant's thirteen
    // points that is the difference between a 152-byte and a 243-byte update -
    // measured, not guessed. On a metered 4G link it is most of the saving
    // Sparkplug exists to provide, so it is opt-in.
    uint64_t timestamp = 0;
    bool hasTimestamp = false;

    // is_historical: this reading is from the past and MUST NOT update a live
    // tag. What store-and-forward publishes when a link comes back.
    bool isHistorical = false;

    // is_transient: do not store this as a tag at all.
    bool isTransient = false;

    MqttSparkplugProperty properties[MQ_SP_MAX_PROPERTIES];
    size_t propertyCount = 0;

    bool addProperty(const MqttSparkplugProperty& property) {
        if (propertyCount >= MQ_SP_MAX_PROPERTIES) return false;
        properties[propertyCount++] = property;
        return true;
    }

    const MqttSparkplugProperty* findProperty(const char* key) const;
};

// --- One payload ---

struct MqttSparkplugPayload {
    // [tck-id-topics-nbirth-timestamp] The NBIRTH MUST include a timestamp
    // denoting the date and time the message was sent from the Edge Node. Every
    // other message type has the same statement.
    uint64_t timestamp = 0;
    bool hasTimestamp = false;

    // [tck-id-payloads-sequence-num-always-included] on everything except
    // NDEATH, where [tck-id-topics-ndeath-seq] says it MUST NOT be included.
    // Two death messages with opposite rules: DDEATH carries one
    // ([tck-id-payloads-ddeath-seq]) and NDEATH does not.
    uint64_t seq = 0;
    bool hasSeq = false;

    // Schema-identifying string. Nothing in Sparkplug requires it; it is here
    // because R2 says every field encodes and decodes from day one, and
    // because a decoder that dropped it would corrupt a forwarded payload.
    const char* uuid = nullptr;

    // "To optionally bypass the whole definition above" - the schema's own
    // words. An opaque blob some vendors use instead of metrics.
    const uint8_t* body = nullptr;
    uint32_t bodyLength = 0;

    // THE METRICS AND THE NAME ARENA ARE ALLOCATED, AND THE OWNER SIZES THEM.
    //
    // They were arrays of MQ_SP_MAX_METRICS and MQ_SP_NAME_BYTES inside this
    // struct, so every payload cost the same 7 kB on a board whether it was a
    // node's hundred-metric birth or a one-metric death certificate - and a
    // node holds two. Worse, the limit was a compile-time number, and an
    // OpenPLC project cannot pass -D: a site needing sixty metrics could not
    // have them at all. Now a payload is constructed with what it must hold
    // (the defaults are the old numbers), a node grows its own to exactly its
    // birth certificate, and on an ESP32 with PSRAM the storage lives there
    // (mq_allocLarge). `metrics` is still indexed as an array.
    MqttSparkplugMetric* metrics = nullptr;
    size_t metricCount = 0;

    void clear();

    bool addMetric(const MqttSparkplugMetric& metric) {
        if (metricCount >= _metricCapacity) return false;
        metrics[metricCount++] = metric;
        return true;
    }

    // How many metrics, and how many bytes of names, this payload can hold.
    // Zero for both when its storage could not be allocated - then every
    // addMetric() and every decode fails by name (TooManyMetrics) rather than
    // the board faulting.
    size_t capacity() const { return _metricCapacity; }
    size_t nameCapacity() const { return _nameCapacity; }

    // Make room for at least this many metrics and name bytes. GROW ONLY, and
    // a payload that grows is EMPTIED - call it before building, not halfway
    // through. False when the memory is not there; the payload then keeps
    // what it had.
    bool reserve(size_t metricCapacity, size_t nameBytes);

    // Exactly this much room, smaller as well as larger, and EMPTIED. What a
    // long-lived decode payload uses to give back what one large message
    // made it take (MqttSparkplugHost): reserve() only ever grows, so a host
    // that met one birth of ten thousand metrics held two megabytes for the
    // rest of its life. False when the memory is not there; the payload then
    // keeps what it had.
    bool resize(size_t metricCapacity, size_t nameBytes);

    // PROPERTIES THIS PAYLOAD COULD NOT KEEP, as it was decoded: a metric
    // carries at most MQ_SP_MAX_PROPERTIES, and the rest of its property set
    // is read, checked and counted here rather than kept.
    //
    // It failed the whole decode, and was reported as TooManyMetrics - so a
    // host met an Ignition birth carrying engUnit, engLow, engHigh, Quality
    // and a Tooltip on one tag, could not read the birth at all, and lost
    // the node; and its retry loop doubled the name arena until it passed
    // the message's size, because "too many metrics" said to grow. A
    // property is a description of a metric, never its value: the metric
    // with its first four is worth far more than no metric, and the count
    // says that something was left out.
    uint32_t propertiesDropped = 0;

    // --- Name storage, owned here ---
    //
    // A decoded metric name cannot be a span. It arrives length-prefixed and
    // not null-terminated, every caller wants a `const char*`, and terminating
    // it in place would mean writing into the bytes we were handed. So the
    // payload carries an arena and the decoded names point into it.
    //
    // THE CONSEQUENCE IS THE USEFUL PART: a decoded payload's names survive the
    // receive buffer they came from. Its STRING and BYTES VALUES do not - those
    // are still spans, because a value can be large and copying it would put an
    // allocator back on the path. So: names outlive the buffer, values do not.
    //
    // Public because the node interns into it when it builds a payload from its
    // own registry. Not to be written to directly - use intern().
    char* names = nullptr;
    size_t namesUsed = 0;

    // Copies `length` bytes and terminates them. Returns null when the arena is
    // full, which fails the decode by name rather than truncating a name and
    // silently creating a second tag at the far end.
    const char* intern(const uint8_t* bytes, size_t length);
    const char* intern(const char* text);

    // --- Copying, which is NOT the default one ---
    //
    // A default copy would duplicate the arena bytes and leave every name
    // pointer aimed at the ORIGINAL - so a copied payload whose source has
    // gone out of scope has dangling names. Found by AddressSanitizer on the
    // first test that put decoded payloads in a vector, which is the obvious
    // thing to do with them.
    //
    // These re-base any pointer that lies inside the source's arena. A string
    // or bytes VALUE is deliberately left alone: those are spans into the
    // caller's buffer by design, and the contract is that names outlive the
    // buffer and values do not.
    //
    // A copy is constructed with the source's capacity; an assignment keeps
    // its own and grows only if the source's content would not fit.
    MqttSparkplugPayload() : MqttSparkplugPayload(MQ_SP_MAX_METRICS, MQ_SP_NAME_BYTES) {}
    MqttSparkplugPayload(size_t metricCapacity, size_t nameBytes);
    ~MqttSparkplugPayload();
    MqttSparkplugPayload(const MqttSparkplugPayload& other)
        : MqttSparkplugPayload(other._metricCapacity, other._nameCapacity) {
        copyFrom(other);
    }
    MqttSparkplugPayload& operator=(const MqttSparkplugPayload& other) {
        if (this != &other) copyFrom(other);
        return *this;
    }


    // By name, case SENSITIVE - [tck-id-case-sensitivity-metric-names]. A
    // lookup that folded case would find "LEVEL" for a metric the engineer
    // called "level", and then a Host Application would show one tag where
    // there are two.
    const MqttSparkplugMetric* findMetric(const char* name) const;
    const MqttSparkplugMetric* findAlias(uint64_t alias) const;

private:
    void copyFrom(const MqttSparkplugPayload& other);
    const char* rebase(const MqttSparkplugPayload& other,
                       const char* pointer) const;

    // Frees what is held and allocates afresh, empty. False, and holding
    // nothing, when the memory is not there.
    bool allocate(size_t metricCapacity, size_t nameBytes);
    void release();

    size_t _metricCapacity = 0;
    size_t _nameCapacity = 0;
};

// --- Encoding ---
//
// Sized first, written second - the same discipline as MqttCodec, and for the
// same reason: a writer that grew its own buffer would make the discipline
// optional and put an allocator on the hot path.
//
// `type` decides name-versus-alias per [tck-id-payloads-alias-*], so the same
// payload encodes differently for an NBIRTH and an NDATA. Pass the type you are
// about to publish on.

// Exact encoded length in bytes. 0 with an error set if the payload cannot be
// expressed - an unsupported datatype, a metric with neither name nor alias.
// Gives a metric that arrived without a datatype the one its birth declared,
// and reinterprets the value for it: an integer's sign, text or bytes. A value
// that arrived in a field that cannot hold the declared type is not guessed
// at - it becomes NULL, and this returns false. A declared type this library
// does not carry marks the metric valueUnsupported. A metric that did carry
// its datatype is left alone, and this returns whether it matches.
bool mq_sparkplugApplyDatatype(MqttSparkplugMetric& metric, MqttSparkplugDataType declared);

size_t mq_sparkplugSize(const MqttSparkplugPayload& payload,
                        MqttSparkplugType type,
                        MqttSparkplugError& error);

// Writes exactly mq_sparkplugSize() bytes. Returns what it wrote, or 0 with an
// error set - and on failure it has written nothing a caller could mistake for
// a whole payload.
size_t mq_sparkplugEncode(uint8_t* out, size_t capacity,
                          const MqttSparkplugPayload& payload,
                          MqttSparkplugType type,
                          MqttSparkplugError& error);

// --- Decoding ---
//
// Spans point INTO `in`, which must outlive `out`. Same contract as
// MqttPacket's spans, and the same hazard: a decode buffer reused for the next
// message invalidates every name and string in the payload before it.
MqttSparkplugError mq_sparkplugDecode(const uint8_t* in, size_t length,
                                      MqttSparkplugPayload& out);

// What decoding these bytes will need: how many metrics, and how many bytes
// of names, property keys and uuid (each with its terminator). One walk, no
// allocation, and never more than the message could carry - so a host sizes
// its decode payload ONCE, to the message in hand, instead of doubling and
// decoding again (which cost it about 208 bytes for every byte a large
// message held). An over-estimate never an under-estimate: every property key
// is counted, including any past MQ_SP_MAX_PROPERTIES the decode will drop.
// The error a malformed message would give, or None.
MqttSparkplugError mq_sparkplugMeasure(const uint8_t* in, size_t length,
                                       size_t& metrics, size_t& nameBytes);

// --- Templates: a PLC's STRUCT or UDT ---
//
// A Template metric's value is the encoded Payload.Template. A DEFINITION is
// the type - its members with their datatypes and default values, and its
// parameters - published only in the NBIRTH, with is_definition true and no
// template_ref ([tck-id-payloads-template-definition-is-definition],
// [tck-id-payloads-template-definition-ref],
// [tck-id-payloads-template-definition-nbirth-only]); is_definition is written
// on both kinds ([tck-id-payloads-template-is-definition]). An INSTANCE is a value
// of that type: is_definition false, template_ref the definition's name
// ([tck-id-payloads-template-instance-ref]); in a birth with every member
// ([tck-id-payloads-template-instance-members-birth]), in data with those
// that changed.
//
// Members are metrics, and travel by NAME - the encoder writes each member's
// name whatever message the template goes in. A member can itself be a
// Template (a struct in a struct), an array or a dataset.
#ifndef MQ_SP_MAX_PARAMETERS
#define MQ_SP_MAX_PARAMETERS 8
#endif

struct MqttSparkplugTemplate {
    // Optional, the schema's words: "the version of the Template to prevent
    // mismatches".
    const char* version = nullptr;

    // An instance's definition, by name; null on a definition.
    const char* templateRef = nullptr;
    bool isDefinition = false;

    // A parameter is a name, a type and a scalar value - a property in all
    // but its field numbers, so it is one, its name in `key`.
    MqttSparkplugProperty parameters[MQ_SP_MAX_PARAMETERS];
    size_t parameterCount = 0;

    // The member metrics, and the arena a decode interns their names (and
    // the version, ref and parameter names) into. Sized like any payload.
    MqttSparkplugPayload members;

    MqttSparkplugTemplate() = default;
    MqttSparkplugTemplate(size_t memberCapacity, size_t nameBytes)
        : members(memberCapacity, nameBytes) {}
    // Not copied: its strings point into its own arena.
    MqttSparkplugTemplate(const MqttSparkplugTemplate&) = delete;
    MqttSparkplugTemplate& operator=(const MqttSparkplugTemplate&) = delete;

    bool addParameter(const MqttSparkplugProperty& parameter) {
        if (parameterCount >= MQ_SP_MAX_PARAMETERS) return false;
        parameters[parameterCount++] = parameter;
        return true;
    }
    bool addMember(const MqttSparkplugMetric& member) {
        return members.addMetric(member);
    }
    void clear();
};

// Exact encoded length, or 0 with an error set: a definition with a
// template_ref or an instance without one (TemplateReference), a member with
// no name (InvalidName), a value its datatype cannot hold.
size_t mq_sparkplugTemplateSize(const MqttSparkplugTemplate& value,
                                MqttSparkplugError& error);
size_t mq_sparkplugEncodeTemplate(uint8_t* out, size_t capacity,
                                  const MqttSparkplugTemplate& value,
                                  MqttSparkplugError& error);

// Into a caller-owned template; members' values are spans into `in`, as a
// payload's are.
MqttSparkplugError mq_sparkplugDecodeTemplate(const uint8_t* in, size_t length,
                                              MqttSparkplugTemplate& out);

// Only whether it is a definition and the name it references, without
// decoding its members - what a node checks an instance against its
// definitions with. `ref` is a span into `in`, null when there is none.
bool mq_sparkplugTemplateHeader(const uint8_t* in, size_t length,
                                bool& isDefinition, const uint8_t*& ref,
                                size_t& refLength);

// --- DataSets: a table ---
//
// Columns with names and types, then rows of cells. A column's type is one of
// the scalars [tck-id-payloads-dataset-types-value] allows - the integers,
// Float, Double, Boolean, String, DateTime, Text - and each row has a cell
// for every column ([tck-id-payloads-dataset-parameter-type-req] and its
// siblings). A null cell travels as an empty value: the schema has no is_null
// for one.
struct MqttSparkplugDataSetColumn {
    const char* name = nullptr;
    MqttSparkplugDataType type = MqttSparkplugDataType::Unknown;
};

// Whether a DataSet column can be this type.
bool mq_sparkplugDataSetTypeAllowed(MqttSparkplugDataType type);

// `cells` is row-major, rowCount * columnCount of them, each of its column's
// type or null. Exact length, or 0 with ValueTypeMismatch for a cell of the
// wrong type, DataTypeNotSupported for a column type a DataSet cannot have.
size_t mq_sparkplugDataSetSize(const MqttSparkplugDataSetColumn* columns,
                               size_t columnCount,
                               const MqttSparkplugValue* cells, size_t rowCount,
                               MqttSparkplugError& error);
size_t mq_sparkplugEncodeDataSet(uint8_t* out, size_t capacity,
                                 const MqttSparkplugDataSetColumn* columns,
                                 size_t columnCount,
                                 const MqttSparkplugValue* cells,
                                 size_t rowCount, MqttSparkplugError& error);

// Reads an encoded DataSet where it lies: nothing is copied, a column name
// and a String cell are spans into it. open() checks the whole of it once -
// as many names and types as columns, a cell for every column in every row,
// each in its column's field - so column() and cell() cannot meet a
// malformed one.
//
// LINEAR IN THE TABLE, read in order. open() checked every cell against its
// column by walking the column list again for each one, and cell() walked
// from the first row for each call: a hostile 400 kB table of one-cell rows
// kept a host's poll busy for minutes, and an honest one of ten thousand rows
// read in a loop was quadratic. Now open() is one pass with the column types
// cached (MQ_SP_DATASET_TYPE_CACHE of them in the reader, any more in a
// buffer allocated for the pass and freed), and cell() resumes from the cell
// it read last, so a row-major loop costs one step a cell. Random access
// still works; it walks from the nearest point it knows.
#ifndef MQ_SP_DATASET_TYPE_CACHE
#define MQ_SP_DATASET_TYPE_CACHE 32
#endif

class MqttSparkplugDataSetReader {
public:
    MqttSparkplugError open(const uint8_t* data, size_t length);
    MqttSparkplugError open(const MqttSparkplugValue& dataSet) {
        return open(dataSet.as.bytes.data, dataSet.as.bytes.length);
    }

    size_t columnCount() const { return _columns; }
    size_t rowCount() const { return _rows; }

    bool column(size_t index, const uint8_t*& name, size_t& nameLength,
                MqttSparkplugDataType& type) const;
    // A cell as a value of its column's type; isNull for an empty one.
    bool cell(size_t row, size_t column, MqttSparkplugValue& out) const;

private:
    bool typeOf(size_t column, MqttSparkplugDataType& type) const;

    const uint8_t* _data = nullptr;
    size_t _length = 0;
    size_t _columns = 0;
    size_t _rows = 0;

    // The first columns' types, read once by open().
    uint8_t _types[MQ_SP_DATASET_TYPE_CACHE] = {};

    // Where the last cell() left off: the row it read, the offset of that
    // row's field in the table, and the offset of the cell after the one it
    // returned. A row-major loop resumes here rather than starting again.
    mutable size_t _cursorRow = 0;
    mutable size_t _cursorRowAt = 0;     // offset of row _cursorRow's tag
    mutable size_t _cursorColumn = 0;    // the next cell's column
    mutable size_t _cursorCellAt = 0;    // offset of that cell's tag in the row
    mutable bool _cursorValid = false;
};

// --- PropertySets as values ---
//
// A property whose value is a PropertySet, or a PropertySetList - a list of
// them. Encoded here, carried as bytes, read back here; keys are interned
// into `names` (any payload's arena).
size_t mq_sparkplugEncodePropertySet(uint8_t* out, size_t capacity,
                                     const MqttSparkplugProperty* properties,
                                     size_t count, MqttSparkplugError& error);
MqttSparkplugError mq_sparkplugDecodePropertySet(
    const uint8_t* in, size_t length, MqttSparkplugProperty* properties,
    size_t capacity, size_t& count, MqttSparkplugPayload& names);

// A list from sets already encoded; the length, written only if it fits.
size_t mq_sparkplugEncodePropertySetList(uint8_t* out, size_t capacity,
                                         const uint8_t* const* sets,
                                         const size_t* lengths, size_t count);
// The list's sets, one at a time, as spans into `in`. False past the end or
// for a malformed list.
bool mq_sparkplugPropertySetListAt(const uint8_t* in, size_t length,
                                   size_t index, const uint8_t*& set,
                                   size_t& setLength);

// --- The STATE payload, which is JSON and not protobuf ---
//
// [tck-id-payloads-state-will-message-payload] The Death Certificate Payload
// MUST be JSON UTF-8 data. It MUST include two key/value pairs where one key
// MUST be online and it's value is a boolean false. The other key MUST be
// timestamp and the value MUST be a numeric value representing the current UTC
// time in milliseconds since Epoch.
//
// Two keys and two value types, so this is a purpose-built fifty lines rather
// than a JSON dependency. Nothing else in this library parses JSON, and taking
// one on to read a single flat object would put a third-party parser on the
// network-facing path and oblige us to fuzz it.
//
// NOTE FOR THE HOST SIDE: [tck-id-payloads-state-birth-payload] requires the
// birth's timestamp to MATCH the value used in the Will of the immediately
// preceding CONNECT. So a host chooses the number once, before connecting, and
// writes it twice - which is why this is a formatter taking a timestamp rather
// than one that reads the clock.
bool mq_sparkplugParseState(const uint8_t* data, size_t length,
                            bool& online, uint64_t& timestamp);

size_t mq_sparkplugWriteState(char* out, size_t capacity, bool online,
                              uint64_t timestamp);

// --- Primitives, exposed for the tests ---
//
// A codec whose varint reader is private is a codec whose varint reader is
// tested only through six layers of message. These are the four functions every
// byte goes through, so they are tested directly and the fuzzer drives them.

size_t mq_pbVarintSize(uint64_t value);
size_t mq_pbWriteVarint(uint8_t* out, size_t capacity, uint64_t value);

// `consumed` is set even on failure, so a caller can report where.
MqttSparkplugError mq_pbReadVarint(const uint8_t* in, size_t available,
                                   uint64_t& value, size_t& consumed);

inline size_t mq_pbTagSize(uint32_t field) {
    return mq_pbVarintSize((uint64_t)field << 3);
}
